from lib import *
S = SS('f9')
R = J('f9'); rc = R['race']; wk = R['workers']; fa = R['factory']
steps = [
    step("Flask 3.1.3 里 @app.before_first_request 已经不存在:hasattr(app, 'before_first_request') 是 False,使用它抛 AttributeError: 'Flask' object has no attribute 'before_first_request';Flask 类上以 before 开头的方法只剩 before_request。需要「第一次请求前做一次」的逻辑要自己换方案。", t=tl(S(1)), mark=lidx(S(1), 'AttributeError', '= False'), kv=KV([['Flask 版本', '3.1.3'], ['before_first_request', '不存在'], ['剩下的', 'before_request']], ['before_first_request'])),
    step(f"方案 A:在应用工厂里初始化。with app.app_context(): warm_up() 放在 create_app() 里,启动时执行一次:create_app() 耗时 {fa[0]} ms(含 50 ms 的 warm_up),之后 5 个请求 warm_up 总共执行 {fa[1]} 次。初始化发生在接收请求之前,代价是启动变慢。", t=tl(S(2)), done=lidx(S(2), 'create_app() 耗时'), kv=KV([['create_app() 耗时', f'{fa[0]} ms'], ['warm_up 执行次数', str(fa[1])]], ['warm_up 执行次数'])),
    step(f"方案 B:before_request 里用标志位。真实 gunicorn(1 个 worker、16 线程)下 12 个并发的第一批请求:不加锁的版本 init 执行了 {rc['nolock']} 次(每个并发请求都发现标志位还没设置);加了线程锁并二次检查的版本执行 {rc['lock']} 次;写在模块级(导入时执行)的版本执行 {rc['module']} 次。所有请求都返回 200。", t=tl(S(3)), mark=lidx(S(3), 'MODE=nolock'), done=lidx(S(3), 'MODE=lock', 'MODE=module'), b=bars([['不加锁', rc['nolock'], f"{rc['nolock']} 次"], ['加锁', rc['lock'], f"{rc['lock']} 次"], ['模块级', rc['module'], f"{rc['module']} 次"]], rc['nolock'], done=[0, 1, 2]), kv=KV([['不加锁', f"{rc['nolock']} 次"], ['加锁 + 二次检查', f"{rc['lock']} 次"], ['模块级', f"{rc['module']} 次"]], ['不加锁'])),
    step(f"多个 worker 进程:--workers 3、模块级初始化,init 执行 {wk['--workers 3'][0]} 次、涉及 {wk['--workers 3'][1]} 个不同的 pid(每个 worker 进程各一次);加 --preload(主进程先导入应用,再 fork 出 worker)变成 {wk['--workers 3 --preload'][0]} 次、{wk['--workers 3 --preload'][1]} 个 pid。方案 B 的线程锁换成 3 个 worker 时仍然执行 {wk['lock3'][0]} 次、涉及 {wk['lock3'][1]} 个 pid:线程锁只在进程内有效,跨进程的「只做一次」要靠外部手段(数据库、文件锁、迁移步骤)。", t=tl(S(4)), mark=lidx(S(4), '--workers 3 MODE=lock'), done=lidx(S(4), '--preload'), kv=KV([['--workers 3', f"{wk['--workers 3'][0]} 次(3 个 pid)"], ['+ --preload', f"{wk['--workers 3 --preload'][0]} 次(1 个 pid)"], ['线程锁 + 3 worker', f"{wk['lock3'][0]} 次(3 个 pid)"]], ['线程锁 + 3 worker'])),
]
A = mkartf('f9', 9, 'Flask,before_first_request,应用工厂,gunicorn,真实验证,动画演示',
    f'Flask 3.1.3 已经没有 before_first_request:改用应用工厂里初始化(一次),或 before_request 加锁(不加锁时 12 个并发请求执行了 {rc["nolock"]} 次 init);gunicorn 3 个 worker 各执行一次,--preload 变成 1 次,线程锁挡不住多进程。',
    '很多旧教程里的 @app.before_first_request 在新版本里报错。要实现「第一次请求前做一次」应该怎么写?并发和多进程下会不会重复执行?这篇用真实的 gunicorn 并发请求一一数出来。',
    [('不存在', 'Flask 3.1.3 里 before_first_request 的状态'), (f"{rc['nolock']} → {rc['lock']}", '12 个并发首批请求下 init 执行次数:不加锁 → 加锁'), (f"{wk['--workers 3'][0]} → {wk['--workers 3 --preload'][0]}", '3 个 worker 下模块级 init 执行次数:默认 → --preload')],
    [('before_first_request 没了', '<p>上一篇:<a href="flask-before-after-teardown.html">before_request、after_request、teardown_request</a>;下一篇:<a href="flask-error-handler-order.html">异常处理器的匹配顺序</a>。</p>'), ('应用工厂里初始化', None), ('before_request 加标志位', None), ('多个 worker 进程', None)],
    steps, [ENV_F + '。gunicorn --threads 16 / --workers 3', '没有验证:uWSGI 的 lazy-apps 与预加载差别(见第 173 篇)、Flask 2.2 之前 before_first_request 的旧行为(本机只有 3.1.3)、flask run 开发服务器下的重载器对初始化次数的影响', '「方案 B 不加锁会重复执行」是在 init 里放了 0.2 秒的 sleep 来放大竞态后测得的次数,真实应用里的次数取决于初始化耗时与并发量'], '第一次请求前的初始化')
